-- 0012 budget_items: an event's planned and actual income and costs (KPI reference §3.4 finance, §3.10 organizer local
--   spend). Generated by drizzle-kit from src/db/schema.ts; no hand edits below this header. Server-only like
--   organization_invitations: RLS on, a SELECT policy for owner/admin, and (explicit-grant model since 0006) no privilege
--   for anon/authenticated.
CREATE TABLE "budget_items" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"organization_id" uuid NOT NULL,
	"event_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"category" text NOT NULL,
	"label" varchar(200) NOT NULL,
	"planned_kurus" bigint,
	"actual_kurus" bigint,
	"quantity" integer,
	"cost_behavior" text,
	"supplier_local" boolean,
	"funded_externally" boolean,
	"notes" text,
	"created_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "budget_items_kind_category" CHECK (("budget_items"."kind" = 'INCOME' and "budget_items"."category" in ('TICKETS', 'SPONSORSHIP', 'EXHIBITOR', 'GRANT', 'MERCHANDISE', 'OTHER'))
      or ("budget_items"."kind" = 'COST' and "budget_items"."category" in ('VENUE', 'PRODUCTION', 'CATERING', 'MARKETING', 'STAFF', 'SECURITY', 'LOGISTICS', 'ARTISTS_SPEAKERS', 'PERMITS_INSURANCE', 'OTHER'))
      or ("budget_items"."kind" = 'TICKET_ADJUSTMENT' and "budget_items"."category" in ('REFUND', 'DISCOUNT'))),
	CONSTRAINT "budget_items_amounts" CHECK (("budget_items"."planned_kurus" is not null or "budget_items"."actual_kurus" is not null)
      and ("budget_items"."planned_kurus" is null or "budget_items"."planned_kurus" between 0 and 10000000000000)
      and ("budget_items"."actual_kurus" is null or "budget_items"."actual_kurus" between 0 and 10000000000000)),
	CONSTRAINT "budget_items_label_not_blank" CHECK (length(trim("budget_items"."label")) > 0),
	CONSTRAINT "budget_items_quantity" CHECK ("budget_items"."quantity" is null or ("budget_items"."kind" = 'INCOME' and "budget_items"."category" = 'TICKETS' and "budget_items"."quantity" >= 0)),
	CONSTRAINT "budget_items_cost_fields" CHECK ("budget_items"."kind" = 'COST' or ("budget_items"."cost_behavior" is null and "budget_items"."supplier_local" is null and "budget_items"."funded_externally" is null)),
	CONSTRAINT "budget_items_cost_behavior" CHECK ("budget_items"."cost_behavior" is null or "budget_items"."cost_behavior" in ('FIXED', 'VARIABLE'))
);
